package mz.bam.seeky.android;
import android.content.*;import android.text.*;import android.text.method.LinkMovementMethod;import android.text.style.ClickableSpan;import android.view.View;import android.widget.*;import java.util.*;import java.util.regex.*;
final class StudySources {
 static void link(StudyAssistantActivity a,TextView view,String answer,SeekyAiStore.Session owner){List<StudyEvidence.Part> parts=StudyEvidence.parts(owner.context());SpannableString text=new SpannableString(answer);Matcher matcher=StudyEvidence.CITATION.matcher(answer);while(matcher.find()){int n=Integer.parseInt(matcher.group(1));if(n>parts.size())continue;final StudyEvidence.Part part=parts.get(n-1);text.setSpan(new ClickableSpan(){public void onClick(View v){show(a,owner,part);}public void updateDrawState(TextPaint ds){ds.setColor(a.colors.accent);ds.setUnderlineText(true);}},matcher.start(),matcher.end(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}view.setText(text);view.setMovementMethod(LinkMovementMethod.getInstance());}
 static void source(StudyAssistantActivity a,SeekyAiStore.Session owner){List<StudyEvidence.Part> parts=StudyEvidence.parts(owner.context());if(parts.isEmpty())return;String[] labels=new String[parts.size()];for(int i=0;i<labels.length;i++)labels[i]="[T"+parts.get(i).number+"] "+AudioTitles.limit(parts.get(i).text.replace('\n',' '),90,256);new UiDialog.Builder(a).setTitle(owner.s("label")).setItems(labels,(d,n)->show(a,owner,parts.get(n))).setNegativeButton("Fechar",null).show();}
 static void show(StudyAssistantActivity a,SeekyAiStore.Session owner,StudyEvidence.Part part){TextView text=PlusUi.text(a,part.text,16);text.setTextIsSelectable(true);ScrollView scroll=new ScrollView(a);scroll.addView(text);UiDialog.Builder dialog=new UiDialog.Builder(a).setTitle(owner.s("title")+" · "+owner.s("label")+" · [T"+part.number+"]").setView(scroll).setPositiveButton("Fechar",null);if(!owner.s("uri").isEmpty())dialog.setNeutralButton("Abrir origem",(d,w)->PlusUi.run(a,()->{long material=owner.n("material");boolean same=owner.s("workspace_id").equals(a.getSharedPreferences("reading_tools",0).getString("workspace_id",""));if(material>0)try(StudyStore db=new StudyStore(a)){StudyStore.Row row=db.get("materials",material);same&=row!=null&&(owner.s("source_hash").isEmpty()||row.s("hash").equals(owner.s("source_hash")));}if(!same){PlusUi.post(a,()->PlusUi.toast(a,"O trecho da conversa foi conservado; o livro de origem mudou."));return;}PlusUi.post(a,()->a.startActivity(new Intent(a,ReaderActivity.class).setDataAndType(android.net.Uri.parse(owner.s("uri")),owner.s("mime")).putExtra("name",owner.s("name")).putExtra("study_title",owner.s("title")).putExtra("study_material",material).putExtra("study_segment",(int)owner.n("part"))));}));dialog.show();}
 static void cards(StudyAssistantActivity a,String answer,SeekyAiStore.Session owner){List<StudyCards.Card> cards;try{cards=StudyCards.parse(answer);}catch(Exception e){PlusUi.error(a,e);return;}if(cards.isEmpty()){LinearLayout form=PlusUi.column(a);EditText front=PlusUi.input(a,"Pergunta / frente","",5000),back=PlusUi.input(a,"Resposta / verso",answer,20000);front.setMinLines(2);back.setMinLines(4);form.addView(front);form.addView(back);new UiDialog.Builder(a).setTitle("Cartão de revisão").setView(form).setPositiveButton("Guardar",(d,w)->{try{save(a,owner,Collections.singletonList(new StudyCards.Card(front.getText().toString(),back.getText().toString(),"")));}catch(Exception e){PlusUi.error(a,e);}}).setNegativeButton("Cancelar",null).show();return;}String[] labels=new String[cards.size()];boolean[] chosen=new boolean[cards.size()];Arrays.fill(chosen,true);for(int i=0;i<labels.length;i++){StudyCards.Card card=cards.get(i);labels[i]=card.front+"\n\n"+card.back+"\n"+owner.s("label")+" · "+StudyEvidence.valid(card.refs,owner.context());}final List<StudyCards.Card> values=cards;new UiDialog.Builder(a).setTitle("Rever cartões antes de guardar").setMultiChoiceItems(labels,chosen,(d,n,on)->chosen[n]=on).setPositiveButton("Guardar seleccionados",(d,w)->{List<StudyCards.Card> selected=new ArrayList<>();for(int i=0;i<chosen.length;i++)if(chosen[i])selected.add(values.get(i));if(selected.isEmpty())PlusUi.toast(a,"Escolha pelo menos um cartão.");else save(a,owner,selected);}).setNegativeButton("Cancelar",null).show();}
 static void save(StudyAssistantActivity a,SeekyAiStore.Session owner,List<StudyCards.Card> cards){PlusUi.run(a,()->{try(StudyStore db=new StudyStore(a)){long mid=owner.n("material"),sid=owner.n("subject");if(!owner.s("workspace_id").equals(a.getSharedPreferences("reading_tools",0).getString("workspace_id",""))){mid=0;sid=0;}if(mid>0){StudyStore.Row row=db.get("materials",mid);if(row==null||!owner.s("source_hash").isEmpty()&&!owner.s("source_hash").equals(row.s("hash"))){mid=0;sid=0;}else sid=row.n("subject");}if(sid>0&&db.get("subjects",sid)==null)sid=0;android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(StudyCards.Card card:cards){List<Integer> references=StudyEvidence.valid(card.refs,owner.context());String source=owner.s("title")+" · "+owner.s("label")+(references.isEmpty()?"":" · "+references);db.save("cards",0,StudyStore.values("subject",sid,"material",mid,"segment",owner.n("part"),"front",card.front,"back",card.back+"\n\n"+AppLanguage.text(a,"Fonte")+": "+source,"tags","Seeky IA","due",System.currentTimeMillis(),"updated",System.currentTimeMillis()));}sql.setTransactionSuccessful();}finally{sql.endTransaction();}}StudyEvents.changed();PlusUi.post(a,()->PlusUi.toast(a,cards.size()+" "+AppLanguage.text(a,"cartões guardados para revisão")));});}
 private StudySources(){}
}
